type Challenge = {
  title: string;
  description: string;
  side: "left" | "right";
  icon: SvgIconComponent;
};

const getChallengesData = (t: (key: string) => string): Challenge[] => [
  {
    title: t("parents_solutions.challenges[0].title"),
    description: t("parents_solutions.challenges[0].description"),
    side: "left",
    icon: SozYodlashIcon,
  },
  {
    title: t("parents_solutions.challenges[1].title"),
    description: t("parents_solutions.challenges[1].description"),
    side: "right",
    icon: RavonIcon,
  },
  {
    title: t("parents_solutions.challenges[2].title"),
    description: t("parents_solutions.challenges[2].description"),
    side: "left",
    icon: EshitibIcon,
  },
  {
    title: t("parents_solutions.challenges[3].title"),
    description: t("parents_solutions.challenges[3].description"),
    side: "right",
    icon: ReadIcon,
  },
  {
    title: t("parents_solutions.challenges[4].title"),
    description: t("parents_solutions.challenges[4].description"),
    side: "left",
    icon: MatnIcon,
  },
];

export default function ParentsSolutionsChallenges() {
  const { t } = useTranslation();
  const challenges = getChallengesData(t);
  return (
    <section className="w-full bg-white px-5 pb-16 pt-6 sm:px-8 sm:pb-20 sm:pt-10 lg:pb-24">
      <div className="mx-auto max-w-360 px-6 sm:px-8">
        <div className="mx-auto max-w-5xl text-center">
          <h2 className="text-3xl font-bold leading-[1.06] text-(--brand-dark) md:text-4xl lg:text-5xl">
            {t("parents_solutions.challenges_title")}
            <br />
            {t("parents_solutions.question")}
          </h2>
        </div>

        <div className="relative mt-10 sm:mt-12 lg:mt-14">
          <div className="pointer-events-none absolute left-1/2 top-0 hidden h-full -translate-x-1/2 border-l-2 border-dashed border-[#97a2ae] lg:block" />

          <div className="space-y-4 sm:space-y-5 lg:space-y-6">
            {challenges.map((item) => {
              const Icon = item.icon;
              const isLeft = item.side === "left";

              return (
                <div
                  key={item.title}
                  className="relative lg:grid lg:grid-cols-[minmax(0,1fr)_220px_minmax(0,1fr)] lg:items-stretch"
                >
                  <div
                    className={
                      isLeft
                        ? "lg:col-start-1 lg:mr-auto"
                        : "lg:col-start-3 lg:ml-auto"
                    }
                  >
                    <article className="relative mx-auto w-full max-w-[430px] rounded-[34px] bg-(--brand-red) px-5 pb-5 pt-5 text-white sm:px-6 sm:pb-6 sm:pt-6 lg:mx-0">
                      <span
                        className={`absolute top-1/2 hidden h-14 w-1.5 -translate-y-1/2 rounded-full bg-(--brand-dark) lg:block ${isLeft ? "-right-[3px]" : "-left-[3px]"
                          }`}
                      />

                      <div className="flex h-12 w-12 items-center justify-center rounded-full bg-white text-(--brand-dark) sm:h-[54px] sm:w-[54px]">
                        <Icon
                          className="block h-6 w-6 sm:h-7 sm:w-7"
                          aria-hidden="true"
                        />
                      </div>

                      <h3 className="mt-4 text-xl font-bold leading-[1.08] sm:text-2xl lg:text-[30px]">
                        {item.title}
                      </h3>

                      <p className="mt-2 text-sm leading-tight sm:text-base lg:text-[18px]">
                        {item.description}
                      </p>
                    </article>
                  </div>

                  <div className="relative hidden lg:col-start-2 lg:row-start-1 lg:block">
                    <span
                      className={`absolute top-1/2 h-px -translate-y-1/2 border-t-2 border-dashed border-[#97a2ae] ${isLeft ? "left-0 w-1/2" : "right-0 w-1/2"
                        }`}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}
